"use client";

import React, { useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { cn } from "@/lib/utils";

export interface PillButtonProps
  extends Omit<React.HTMLAttributes<HTMLButtonElement>, "onDrag" | "onDragStart" | "onDragEnd" | "onAnimationStart"> {
  label?: string;
}

export function PillButton({
  label = "Capsule Pill",
  className,
  ...props
}: PillButtonProps) {
  const reduceMotion = useReducedMotion();
  const [active, setActive] = useState(false);

  return (
    <motion.button
      type="button"
      onClick={() => setActive(!active)}
      whileHover={reduceMotion ? {} : { scale: 1.05 }}
      whileTap={reduceMotion ? {} : { scale: 0.95 }}
      className={cn(
        "rounded-full px-7 py-3 text-xs font-bold uppercase tracking-wider transition-all select-none cursor-pointer border shadow-lg",
        active
          ? "bg-sky-500 text-white border-sky-400 shadow-sky-500/30"
          : "bg-zinc-900 text-zinc-300 border-zinc-800 hover:bg-zinc-800",
        className
      )}
      {...props}
    >
      {label} {active && "✓"}
    </motion.button>
  );
}

export default PillButton;
